using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;
public static class GrainBatchBaseline {
 static object Field(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
 public static string Run(){var k=GameObject.Find("Corn pile - scoop with left click").GetComponent<CornSurfaceKernels>();k.Rebuild();var samples=(Vector2[])Field(k,"samples");var bs=(Matrix4x4[][])Field(k,"batches");var ids=(int[])Field(k,"sampleBatches");var slots=(int[])Field(k,"sampleSlots");using(var w=new BinaryWriter(File.Open("output/GrainPrototype/spatial-baseline.bin",FileMode.Create))){w.Write(samples.Length);for(int i=0;i<samples.Length;i++){w.Write(ids[i]>=0);if(ids[i]<0)continue;for(int j=0;j<16;j++)w.Write(bs[ids[i]][slots[i]][j]);}}
 var c=SceneView.lastActiveSceneView.camera;var pos=c.transform.position;var rot=c.transform.rotation;var target=c.targetTexture;var active=RenderTexture.active;var rt=RenderTexture.GetTemporary(1100,800,24);var t=new Texture2D(1100,800,TextureFormat.RGB24,false);try{c.transform.position=k.transform.position+new Vector3(-3,3,9);c.transform.rotation=Quaternion.LookRotation(k.transform.position+Vector3.up*1.6f-c.transform.position);c.targetTexture=rt;c.Render();RenderTexture.active=rt;t.ReadPixels(new Rect(0,0,1100,800),0,0);t.Apply();File.WriteAllBytes("output/GrainPrototype/spatial-before.png",t.EncodeToPNG());File.WriteAllText("output/GrainPrototype/spatial-before.txt",k.KernelCount+" kernels, "+k.LastDrawTriangles+" triangles");return k.KernelCount+" kernels, "+k.LastDrawTriangles+" triangles";}finally{c.transform.SetPositionAndRotation(pos,rot);c.targetTexture=target;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(t);}}
}
